5:/**
6: * Golden traces of the Duelist mirror, recorded before the kits changed the step (at commit 4c90df5, by a throwaway
7: * recorder run from outside the repository). A duel created without kits must reproduce them frame by frame: only the
8: * moveset version and the new kit and entity fields (`kit`, `bolt`, `zone`, `obscured`) may differ.
9: *
10: * Each duel is played by a seeded random policy (`mirrorPlayers`) that reads only fields older than the kits, so the
11: * inputs are the recorded ones as long as the states match. For each duel: the hash (`hashState`) of every frame's legacy projection, from frame 0 up to the
12: * result, as one string of 16-digit hashes, and the projection itself as JSON every 300 frames, to diagnose a mismatch.
13: */
14:interface GoldenDuel {
15:  readonly seed: number;
16:  /** Frames stepped up to and including the result. */
17:  readonly frames: number;
18:  readonly result: DuelResult;
19:  readonly hashes: string;
20:  /** The projection at frames 0, 300, 600, ... */
21:  readonly checkpoints: readonly string[];
22:}
23:
24:/** Every field a fighter had before the kits. */
25:const LEGACY_FIGHTER_FIELDS = [
26:  "x",
27:  "y",
28:  "vx",
29:  "vy",
30:  "facing",
31:  "health",
32:  "stamina",
33:  "staminaIdle",
34:  "action",
35:  "actionFrame",
36:  "timer",
37:  "moveId",
38:  "moveHit",
39:  "crouching",
40:  "combo",
41:  "held",
42:  "buffer",
43:] as const;
44:
45:/** The fields the kits added to a fighter, with their value in a duel without kits. */
46:const KIT_FIELDS = { kit: "duelist", bolt: null, zone: null, obscured: false } as const;
47:
48:/** Everything of a state that existed before the kits, but the moveset version. */
49:function legacy(state: DuelState) {
50:  return {
51:    frame: state.frame,
52:    phase: state.phase,
53:    rng: state.rng,
54:    fighters: state.fighters.map((fighter) => Object.fromEntries(LEGACY_FIGHTER_FIELDS.map((field) => [field, fighter[field]]))),
55:    events: state.events,
56:    result: state.result,
57:  };
58:}
59:
60:/** The recorder's input policy, verbatim. */
61:/**
62: * A seeded random player pair for the Duelist mirror. Each player follows random plans (movement, guard, attacks of
63: * every kind, more often up close), and reacts at random to what it sees: it may guard (standing or crouching) when the
64: * opponent starts an attack, try to escape a grab, and follow up on an opponent in hitstun. It reads only fields
65: * that existed before the kits.
66: */
67:function mirrorPlayers(seed: number): (state: DuelState) => DuelInputs {
68:  let rng = seed;
69:  const draw = (bound: number) => {
70:    const drawn = nextInt(rng, bound);
71:    rng = drawn.state;
72:    return drawn.value;
73:  };
74:  const held = [0, 0];
75:  const left = [0, 0];
76:  return (state) => {
77:    for (const player of [0, 1] as const) {
78:      const self = state.fighters[player];
79:      const other = state.fighters[player === 0 ? 1 : 0];
80:      const back = self.x < other.x ? I("left") : I("right");
81:      const forward = self.x < other.x ? I("right") : I("left");
82:      const gap = Math.abs(self.x - other.x);
83:      if (self.action === "thrown" && self.actionFrame >= 2 && draw(100) < 7) {
84:        held[player] = I("light", "heavy");
85:        left[player] = 1;
86:      } else if (other.action === "attack" && other.actionFrame === 1 && gap < 2400 && draw(100) < 50) {
87:        held[player] = back | (draw(100) < 35 ? I("down") : 0);
88:        left[player] = other.timer + 2;
89:      } else if (other.action === "hitstun" && other.actionFrame === 1 && gap < 1600 && draw(100) < 50) {
90:        held[player] = [I("light"), I("heavy"), I("down", "light"), I("special1")][draw(4)]!;
91:        left[player] = 1;
92:      } else if (left[player] === 0) {
93:        const approach = gap > 2400 ? [forward, forward, forward, I("dash")] : [];
94:        const moves = [0, back, back, back | I("down"), forward, forward, forward, I("down"), I("up") | forward, I("dash"), back | I("dash"), I("left", "right"), ...approach];
95:        const attacks = [I("light"), I("light"), I("heavy"), I("down", "heavy"), forward | I("heavy"), I("down", "light"), I("special1"), I("special2"), I("light", "heavy"), I("light", "heavy")];
96:        const attack = draw(100) < (gap < 1800 ? 45 : 10);
97:        held[player] = attack ? attacks[draw(attacks.length)]! : moves[draw(moves.length)]!;
98:        left[player] = attack || (held[player]! & I("up")) !== 0 ? 1 + draw(2) : 1 + draw(16);
99:      }
100:      left[player]!--;
101:    }
102:    return [held[0]!, held[1]!];
103:  };
104:}
